window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4ddd813e03c2dcde"]={"versions": [{"id": "FIG-4ddd813e03c2dcde", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockdiagramm und Testaufbau-Architekturdiagramm für einen End-to-End-(E2E)-Systemtest (Testfallkonfiguration STC_E2E_00001, „Nominal AP Apps for E2E Protection“) im Kontext der AUTOSAR Adaptive Platform. Das Diagramm gliedert sich in eine obere Metadatentabelle der Testkonfiguration und eine untere Systemtopologie mit drei Knoten: zwei Steuergeräteknoten (ECU1 und ECU2) sowie einem Teststeuerungs- und Automatisierungsknoten (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Hauptblöcke und eine tabellarische Konfiguration:</p>\n<ul class=\"fig-list\"><li><strong>Tabelle (Configuration ID STC_E2E_00001)</strong>:\n<ul class=\"fig-list\"><li>Description: „Nominal AP Apps for E2E Protection“\n</li><li>ECU 1: „Intel MinnowBoard Turbot, 192.168.100.5“\n</li><li>ECU 2: „Renesas R-Car H3 ULCB, 192.168.100.2“\n</li><li>Jenkins: „Jenkins Server, 192.168.100.10“\n</li></ul>\n</li><li><strong>ECU1 (Intel MinnowBoard)</strong>:\n<ul class=\"fig-list\"><li>Hardware: Intel MinnowBoard\n</li><li>Betriebssystem: Linux with Real-time Patches\n</li><li>Betriebssystem-Bibliotheken: POXIS libs (libc, ...)\n</li><li>Plattformdienste / Middleware: vSomeIP, Diagnostic Manager\n</li><li>Laufzeitumgebung: ARA (AUTOSAR Runtime for Adaptive Applications)\n</li><li>Anwendungsschicht: Video Data\n</li></ul>\n</li><li><strong>ECU2 (Renesas R-CAR H3 ULCB)</strong>:\n<ul class=\"fig-list\"><li>Hardware: Renesas R-CAR H3 ULCB\n</li><li>Betriebssystem: Linux with Real-time Patches\n</li><li>Betriebssystem-Bibliotheken: POXIS libs (libc, ...)\n</li><li>Plattformdienste / Middleware: vSomeIP, Diagnostic Manager\n</li><li>Laufzeitumgebung: ARA\n</li><li>Anwendungsschicht: System Test Applications\n</li></ul>\n</li><li><strong>Jenkins (PC)</strong>:\n<ul class=\"fig-list\"><li>Hardware: PC\n</li><li>Betriebssystem: Linux\n</li><li>Automatisierungsumgebung: Jenkins\n</li><li>Testanwendung: E2E Tester\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Verbindungen</strong>:\n<ul class=\"fig-list\"><li>Vertikale gestrichelte Verbindungen innerhalb der Knoten zur Schichtenkopplung (Hardware -&gt; OS -&gt; Libs -&gt; Middleware/ARA -&gt; Anwendungen).\n</li><li>Horizontale gestrichelte Leitungen auf Hardware-/Netzwerkebene zur Vernetzung der drei Zielknoten über Ethernet/IP (192.168.100.x-Subnetz).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichten- und Bereitstellungsmodell ohne explizite zeitliche Interaktionssequenzen. Gestrichelte rote Linien mit Pfeilspitzen signalisieren den Signal- und Kontrollfluss von den Plattform- und Middleware-Komponenten (vSomeIP, Diagnostic Manager, ARA bzw. Jenkins-Framework) aufwärts zu den Test- und Applikationsinstanzen („Video Data“, „System Test Applications“, „E2E Tester“). Auf Infrastrukturebene verbindet das IP-Netzwerk den Jenkins-Server zur Testorchestrierung und Ergebnisabfrage mit ECU1 und ECU2, über welches auch die E2E-geschützte Dienstkommunikation (vSomeIP/SOME/IP) zwischen den Applikationen übertragen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert das Referenz-Testsetup für normative E2E-Validierungstests nach AUTOSAR Adaptive Platform System Tests. Implementierer von E2E-Systemtests müssen sicherstellen, dass die Applikationsknoten über standardkonforme POSIX-Betriebssysteme mit Echtzeiterweiterung verfügen und AUTOSAR ARA zusammen mit der SOME/IP-Kommunikation und dem Diagnostic Manager bereitstellen. Die IP-Adressierung und Zuordnung der Testinstanzen zu ECU1 (192.168.100.5), ECU2 (192.168.100.2) und Jenkins (192.168.100.10) dient als normative Testumgebungsreferenz für die Konfiguration STC_E2E_00001. Die Schichtbezeichnung „POXIS libs (libc, ...)“ weist auf einen Schreibfehler für POSIX hin.</p>"}, {"id": "FIG-4ed2871aa495aed9", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockdiagramm und Testaufbau-Architekturdiagramm für einen End-to-End-(E2E)-Systemtest (Testfallkonfiguration STC_E2E_00001, „Nominal AP Apps for E2E Protection“) im Kontext der AUTOSAR Adaptive Platform. Das Diagramm gliedert sich in eine obere Metadatentabelle der Testkonfiguration und eine untere Systemtopologie mit drei Knoten: zwei Steuergeräteknoten (ECU1 und ECU2) sowie einem Teststeuerungs- und Automatisierungsknoten (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Hauptblöcke und eine tabellarische Konfiguration:</p>\n<ul class=\"fig-list\"><li><strong>Tabelle (Configuration ID STC_E2E_00001)</strong>:\n<ul class=\"fig-list\"><li>Description: „Nominal AP Apps for E2E Protection“\n</li><li>ECU 1: „Intel MinnowBoard Turbot, 192.168.100.5“\n</li><li>ECU 2: „Renesas R-Car H3 ULCB, 192.168.100.2“\n</li><li>Jenkins: „Jenkins Server, 192.168.100.10“\n</li></ul>\n</li><li><strong>ECU1 (Intel MinnowBoard)</strong>:\n<ul class=\"fig-list\"><li>Hardware: Intel MinnowBoard\n</li><li>Betriebssystem: Linux with Real-time Patches\n</li><li>Betriebssystem-Bibliotheken: POSIX libs (libc, ...)\n</li><li>Plattformdienste / Middleware: vSomeIP, Diagnostic Manager\n</li><li>Laufzeitumgebung: ARA (AUTOSAR Runtime for Adaptive Applications)\n</li><li>Anwendungsschicht: E2E Test Application(s)\n</li></ul>\n</li><li><strong>ECU2 (Renesas R-CAR H3 ULCB)</strong>:\n<ul class=\"fig-list\"><li>Hardware: Renesas R-CAR H3 ULCB\n</li><li>Betriebssystem: Linux with Real-time Patches\n</li><li>Betriebssystem-Bibliotheken: POSIX libs (libc, ...)\n</li><li>Plattformdienste / Middleware: vSomeIP, Diagnostic Manager\n</li><li>Laufzeitumgebung: ARA\n</li><li>Anwendungsschicht: E2E Test Application(s)\n</li></ul>\n</li><li><strong>Jenkins (PC)</strong>:\n<ul class=\"fig-list\"><li>Hardware: PC\n</li><li>Betriebssystem: Linux\n</li><li>Automatisierungsumgebung: Jenkins\n</li><li>Testanwendung: E2E Tester\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Verbindungen</strong>:\n<ul class=\"fig-list\"><li>Vertikale gestrichelte Verbindungen innerhalb der Knoten zur Schichtenkopplung (Hardware -&gt; OS -&gt; Libs -&gt; Middleware/ARA -&gt; Anwendungen).\n</li><li>Horizontale gestrichelte Leitungen auf Hardware-/Netzwerkebene zur Vernetzung der drei Zielknoten über Ethernet/IP (192.168.100.x-Subnetz).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichten- und Bereitstellungsmodell ohne explizite zeitliche Interaktionssequenzen. Gestrichelte rote Linien mit Pfeilspitzen signalisieren den Signal- und Kontrollfluss von den Plattform- und Middleware-Komponenten (vSomeIP, Diagnostic Manager, ARA bzw. Jenkins-Framework) aufwärts zu den Test- und Applikationsinstanzen („E2E Test Application(s)“ auf ECU1 und ECU2 sowie „E2E Tester“ auf Jenkins). Auf Infrastrukturebene verbindet das IP-Netzwerk den Jenkins-Server zur Testorchestrierung und Ergebnisabfrage mit ECU1 und ECU2, über welches auch die E2E-geschützte Dienstkommunikation (vSomeIP/SOME/IP) zwischen den Instanzen von E2E Test Application(s) übertragen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert das Referenz-Testsetup für normative E2E-Validierungstests nach AUTOSAR Adaptive Platform System Tests. Implementierer von E2E-Systemtests müssen sicherstellen, dass die Applikationsknoten über standardkonforme POSIX-Betriebssysteme mit Echtzeiterweiterung verfügen und AUTOSAR ARA zusammen mit der SOME/IP-Kommunikation und dem Diagnostic Manager bereitstellen. Beide Steuergeräte führen Instanzen von „E2E Test Application(s)“ aus. Die IP-Adressierung und Zuordnung der Testinstanzen zu ECU1 (192.168.100.5), ECU2 (192.168.100.2) und Jenkins (192.168.100.10) dient als normative Testumgebungsreferenz für die Konfiguration STC_E2E_00001.</p>"}, {"id": "FIG-0ba04c7647be020a", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockdiagramm und Testaufbau-Architekturdiagramm für einen End-to-End-(E2E)-Systemtest (Testfallkonfiguration STC_E2E_00001, „Nominal AP Apps for E2E Protection“) im Kontext der AUTOSAR Adaptive Platform. Das Diagramm gliedert sich in eine obere Metadatentabelle der Testkonfiguration und eine untere Systemtopologie mit drei Knoten: zwei Steuergeräteknoten (ECU1 und ECU2) sowie einem Teststeuerungs- und Automatisierungsknoten (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Hauptblöcke und eine tabellarische Konfiguration:</p>\n<ul class=\"fig-list\"><li><strong>Tabelle (Configuration ID STC_E2E_00001)</strong>:\n<ul class=\"fig-list\"><li>Description: „Nominal AP Apps for E2E Protection“\n</li><li>ECU 1: „Intel MinnowBoard Turbot, 192.168.100.5“\n</li><li>ECU 2: „Renesas R-Car H3 ULCB, 192.168.100.2“\n</li><li>Jenkins: „Jenkins Server, 192.168.100.10“\n</li></ul>\n</li><li><strong>ECU1 (Intel MinnowBoard)</strong>:\n<ul class=\"fig-list\"><li>Hardware: Intel MinnowBoard\n</li><li>Betriebssystem: Linux with Real-time Patches\n</li><li>Betriebssystem-Bibliotheken: POSIX libs (libc, ...)\n</li><li>Plattformdienste / Middleware: vSomeIP, Diagnostic Manager\n</li><li>Laufzeitumgebung: ARA (AUTOSAR Runtime for Adaptive Applications)\n</li><li>Anwendungsschicht: E2E Test Application(s)\n</li></ul>\n</li><li><strong>ECU2 (Renesas R-CAR H3 ULCB)</strong>:\n<ul class=\"fig-list\"><li>Hardware: Renesas R-CAR H3 ULCB\n</li><li>Betriebssystem: Linux with Real-time Patches\n</li><li>Betriebssystem-Bibliotheken: POSIX libs (libc, ...)\n</li><li>Plattformdienste / Middleware: vSomeIP, Diagnostic Manager\n</li><li>Laufzeitumgebung: ARA\n</li><li>Anwendungsschicht: E2E Test Application(s)\n</li></ul>\n</li><li><strong>Jenkins (PC)</strong>:\n<ul class=\"fig-list\"><li>Hardware: PC\n</li><li>Betriebssystem: Linux\n</li><li>Automatisierungsumgebung: Jenkins\n</li><li>Testanwendung: E2E Tester\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Verbindungen</strong>:\n<ul class=\"fig-list\"><li>Vertikale gestrichelte Verbindungen innerhalb der Knoten zur Schichtenkopplung (Hardware -&gt; OS -&gt; Libs -&gt; Middleware/ARA -&gt; Anwendungen).\n</li><li>Horizontale gestrichelte Leitungen auf Hardware-/Netzwerkebene zur Vernetzung der drei Zielknoten über Ethernet/IP (192.168.100.x-Subnetz).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichten- und Bereitstellungsmodell ohne explizite zeitliche Interaktionssequenzen. Gestrichelte rote Linien mit Pfeilspitzen signalisieren den Signal- und Kontrollfluss von den Plattform- und Middleware-Komponenten (vSomeIP, Diagnostic Manager, ARA bzw. Jenkins-Framework) aufwärts zu den Test- und Applikationsinstanzen („E2E Test Application(s)“ auf ECU1 und ECU2 sowie „E2E Tester“ auf Jenkins). Auf Infrastrukturebene verbindet das IP-Netzwerk den Jenkins-Server zur Testorchestrierung und Ergebnisabfrage mit ECU1 und ECU2, über welches auch die E2E-geschützte Dienstkommunikation (vSomeIP/SOME/IP) zwischen den Instanzen von E2E Test Application(s) übertragen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert das Referenz-Testsetup für normative E2E-Validierungstests nach AUTOSAR Adaptive Platform System Tests. Implementierer von E2E-Systemtests müssen sicherstellen, dass die Applikationsknoten über standardkonforme POSIX-Betriebssysteme mit Echtzeiterweiterung verfügen und AUTOSAR ARA zusammen mit der SOME/IP-Kommunikation und dem Diagnostic Manager bereitstellen. Beide Steuergeräte führen Instanzen von „E2E Test Application(s)“ aus. Die IP-Adressierung und Zuordnung der Testinstanzen zu ECU1 (192.168.100.5), ECU2 (192.168.100.2) und Jenkins (192.168.100.10) dient als normative Testumgebungsreferenz für die Konfiguration STC_E2E_00001.</p>"}, {"id": "FIG-cb2eb34563ffe3af", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockdiagramm und Testaufbau-Architekturdiagramm für einen End-to-End-(E2E)-Systemtest (Testfallkonfiguration STC_E2E_00001, „Nominal AP Apps for E2E Protection“) im Kontext der AUTOSAR Adaptive Platform. Das Diagramm gliedert sich in eine obere Metadatentabelle der Testkonfiguration und eine untere Systemtopologie mit drei Knoten: zwei Steuergeräteknoten (ECU1 und ECU2) sowie einem Teststeuerungs- und Automatisierungsknoten (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Hauptblöcke und eine tabellarische Konfiguration:</p>\n<ul class=\"fig-list\"><li><strong>Tabelle (Configuration ID STC_E2E_00001)</strong>:\n<ul class=\"fig-list\"><li>Description: „Nominal AP Apps for E2E Protection“\n</li><li>ECU 1: „Hardware, 192.168.100.5“\n</li><li>ECU 2: „Hardware, 192.168.100.2“\n</li><li>Jenkins: „Jenkins Server, 192.168.100.10“\n</li></ul>\n</li><li><strong>ECU1</strong>:\n<ul class=\"fig-list\"><li>Hardware: Hardware\n</li><li>Betriebssystem: Linux with Real-time Patches\n</li><li>Betriebssystem-Bibliotheken: POSIX libs (libc, ...)\n</li><li>Plattformdienste / Middleware: vSomeIP, Diagnostic Manager\n</li><li>Laufzeitumgebung: ARA (AUTOSAR Runtime for Adaptive Applications)\n</li><li>Anwendungsschicht: E2E Test Application(s)\n</li></ul>\n</li><li><strong>ECU2</strong>:\n<ul class=\"fig-list\"><li>Hardware: Hardware\n</li><li>Betriebssystem: Linux with Real-time Patches\n</li><li>Betriebssystem-Bibliotheken: POSIX libs (libc, ...)\n</li><li>Plattformdienste / Middleware: vSomeIP, Diagnostic Manager\n</li><li>Laufzeitumgebung: ARA\n</li><li>Anwendungsschicht: E2E Test Application(s)\n</li></ul>\n</li><li><strong>Jenkins (PC)</strong>:\n<ul class=\"fig-list\"><li>Hardware: PC\n</li><li>Betriebssystem: Linux\n</li><li>Automatisierungsumgebung: Jenkins\n</li><li>Testanwendung: E2E Tester\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Verbindungen</strong>:\n<ul class=\"fig-list\"><li>Vertikale gestrichelte Verbindungen innerhalb der Knoten zur Schichtenkopplung (Hardware -&gt; OS -&gt; Libs -&gt; Middleware/ARA -&gt; Anwendungen).\n</li><li>Horizontale gestrichelte Leitungen auf Hardware-/Netzwerkebene zur Vernetzung der drei Zielknoten über Ethernet/IP (192.168.100.x-Subnetz).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichten- und Bereitstellungsmodell ohne explizite zeitliche Interaktionssequenzen. Gestrichelte rote Linien mit Pfeilspitzen signalisieren den Signal- und Kontrollfluss von den Plattform- und Middleware-Komponenten (vSomeIP, Diagnostic Manager, ARA bzw. Jenkins-Framework) aufwärts zu den Test- und Applikationsinstanzen („E2E Test Application(s)“ auf ECU1 und ECU2 sowie „E2E Tester“ auf Jenkins). Auf Infrastrukturebene verbindet das IP-Netzwerk den Jenkins-Server zur Testorchestrierung und Ergebnisabfrage mit ECU1 und ECU2, über welches auch die E2E-geschützte Dienstkommunikation (vSomeIP/SOME/IP) zwischen den Instanzen von E2E Test Application(s) übertragen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert das herstellerunabhängige Referenz-Testsetup für normative E2E-Validierungstests nach AUTOSAR Adaptive Platform System Tests. Implementierer von E2E-Systemtests müssen sicherstellen, dass die Applikationsknoten über beliebige geeignete Zielhardware mit POSIX-Betriebssystemen (mit Echtzeiterweiterung) verfügen und AUTOSAR ARA zusammen mit der SOME/IP-Kommunikation und dem Diagnostic Manager bereitstellen. Beide Steuergeräte führen Instanzen von „E2E Test Application(s)“ aus. Die IP-Adressierung und Zuordnung der Testinstanzen zu ECU1 (192.168.100.5), ECU2 (192.168.100.2) und Jenkins (192.168.100.10) dient als normative Testumgebungsreferenz für die Konfiguration STC_E2E_00001.</p>"}], "trans": [{"from": "FIG-4ddd813e03c2dcde", "to": "FIG-4ed2871aa495aed9", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Auf ECU1 und ECU2 wurden die Softwarekomponenten „Video Data“ bzw. „System Test Applications“ einheitlich zu „E2E Test Application(s)“ umbenannt und standardisiert.\n</li><li>Die Bezeichnung der POSIX-Bibliotheksschicht auf ECU1 und ECU2 wurde von „POXIS libs (libc, ...)“ zu „POSIX libs (libc, ...)“ korrigiert.\n</li></ul>"}, {"from": "FIG-4ed2871aa495aed9", "to": "FIG-0ba04c7647be020a", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0ba04c7647be020a", "to": "FIG-cb2eb34563ffe3af", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>In der Konfigurationstabelle wurden für ECU 1 („Intel MinnowBoard Turbot, 192.168.100.5“) und ECU 2 („Renesas R-Car H3 ULCB, 192.168.100.2“) die spezifischen Board-Bezeichnungen durch den generischen Eintrag „Hardware“ ersetzt („Hardware, 192.168.100.5“ bzw. „Hardware, 192.168.100.2“).\n</li><li>Im Hardware-Block von ECU1 wurde die Beschriftung „Intel MinnowBoard“ durch „Hardware“ ersetzt.\n</li><li>Im Hardware-Block von ECU2 wurde die Beschriftung „Renesas R-CAR H3 ULCB“ durch „Hardware“ ersetzt.\n</li></ul>"}]};
